#!/usr/bin/env python3
"""g6_apexlight_unchanged.py - FROZEN gate G6 (PM, 2026-11-20). Do not edit; checked by SHA256SUMS.
Nothing on ApexLight may change.
usage: g6_apexlight_unchanged.py CANDIDATE_APEXLIGHT.gcode LIVE_APEXLIGHT.gcode [--json out.json]   exit 0 PASS, 1 FAIL
PASS iff the two files are byte-identical after removing ONLY OrcaSlicer's wall-clock stamp line
"; generated by OrcaSlicer <ver> on YYYY-MM-DD at HH:MM:SS" (at most one such line per file). Two LIVE slices of the
same request differ only on that line (measured 2026-11-20), so it is not part of the output being protected.
"""
import argparse, hashlib, json, re, sys

STAMP = re.compile(rb"^; generated by OrcaSlicer \S+ on \d{4}-\d{2}-\d{2} at \d{2}:\d{2}:\d{2}\r?$")


def norm(fn):
    lines = open(fn, "rb").read().split(b"\n")
    hits = [i for i, l in enumerate(lines) if STAMP.match(l)]
    if len(hits) > 1:
        raise SystemExit("more than one stamp line in %s" % fn)
    return b"\n".join(l for i, l in enumerate(lines) if i not in hits), len(hits)


def main():
    ap = argparse.ArgumentParser(); ap.add_argument("cand"); ap.add_argument("live"); ap.add_argument("--json")
    a = ap.parse_args()
    c, nc = norm(a.cand); l, nl = norm(a.live)
    fails = []
    first = None
    if c != l:
        first = next((i for i in range(min(len(c), len(l))) if c[i] != l[i]), min(len(c), len(l)))
        fails.append("ApexLight differs from LIVE at normalized byte %d (cand %d bytes, live %d bytes)" % (first, len(c), len(l)))
    rep = {"gate": "G6 apexlight_unchanged", "sha256": hashlib.sha256(open(__file__, "rb").read()).hexdigest(),
           "cand_file": a.cand, "live_file": a.live, "stamp_lines_removed": [nc, nl],
           "cand_sha256_norm": hashlib.sha256(c).hexdigest(), "live_sha256_norm": hashlib.sha256(l).hexdigest(),
           "first_diff_byte": first, "result": "PASS" if not fails else "FAIL", "failures": fails}
    if a.json:
        json.dump(rep, open(a.json, "w"), indent=1)
    print(json.dumps({k: rep[k] for k in ("gate", "result", "failures")}), file=sys.stderr)
    print(json.dumps(rep, indent=1))
    sys.exit(0 if not fails else 1)


if __name__ == "__main__":
    main()
